<script setup>
import {computed} from 'vue'
import {useLearning} from '../useLearning.js'
import {icon} from '../assets.js'
const {state,currentLesson,setAnswer,submitAttempt,hint,loadTaskById,executeTaskAction,setLessonTab}=useLearning()
const names={diagnostic:'先看看从哪里开始',practice:'轮到你试一试',review:'换一道题，检查理解',remediation:'补上这一小步',bridge_demo:'换个学科再看一次'}
const nextAction=computed(()=>state.result?.next_step&&typeof state.result.next_step==='object'?state.result.next_step:null)
const nextText=computed(()=>typeof state.result?.next_step==='string'?state.result.next_step:nextAction.value?.text||nextAction.value?.reason||state.result?.next_step_reason||'')
const nextTask=computed(()=>state.result?.diagnosis?.remedy_task_id||nextAction.value?.task_id||state.next?.task_id||null)
function proceed(){if(!nextTask.value||state.evidenceBusy)return;const action=nextAction.value||state.next;if(action?.task_id===nextTask.value&&action?.lesson_id&&action.lesson_id!==currentLesson.value?.id)return executeTaskAction(action);loadTaskById(nextTask.value,{restart:nextTask.value===state.run?.task.id})}
</script>
<template><section v-if="state.run" class="task-panel"><header class="section-heading"><h2>{{ names[state.run.purpose]||'轮到你试一试' }}</h2><span>{{ state.run.task.kind==='written'?'开放作答 · 待复核':'结果判断' }}</span></header><div v-if="state.run.task.context_table" class="task-context-table"><p>{{ state.run.task.context_table.label }}</p><div tabindex="0" aria-label="阅览室演示数据，可滚动"><table><thead><tr><th>房间</th><th>时段</th><th>可用座位</th><th>占用座位</th></tr></thead><tbody><tr v-for="row in state.run.task.context_table.rows" :key="row.observation_id"><td>{{ row.room }}</td><td>{{ row.time_slot }}</td><td>{{ row.available_seats }}</td><td>{{ row.occupied_seats }}</td></tr></tbody></table></div></div><p class="task-prompt">{{ state.run.task.prompt }}</p><div v-if="state.run.task.kind==='choice'" class="answer-options"><button v-for="option in state.run.task.options" :key="option.id" :class="['answer-option',{selected:state.answer===option.id}]" :aria-pressed="state.answer===option.id" :disabled="!!state.result||state.taskBusy" @click="setAnswer(option.id)"><span>{{ option.id }}</span>{{ option.text }}</button></div><template v-else><textarea :value="state.answer" @input="setAnswer($event.target.value)" :disabled="!!state.result||state.taskBusy" class="written-answer" aria-label="练习作答" rows="5" placeholder="写下你的判断与依据，原始作答会保留。"></textarea><details class="rubric"><summary>查看作答标准</summary><p v-for="item in state.run.task.criteria" :key="item">{{ item }}</p></details></template><div v-if="state.hint" class="hint-feedback" role="status"><strong>一点线索</strong><p>{{ state.hint }}</p><small>这次帮助会随作答记录。</small></div>
<div v-if="!state.result" class="task-actions"><button class="secondary-button" :disabled="state.designPreview||state.hintBusy||state.taskBusy" @click="hint">{{ state.hintBusy?'获取提示中…':'给我一点提示' }}</button><button class="primary-button" :disabled="state.designPreview||!state.answer.trim()||state.taskBusy" @click="submitAttempt">{{ state.taskBusy?'保存与检查中…':'提交作答' }}<img :src="icon('arrow-right','white')" alt=""></button></div>
<section v-else :class="['assessment-feedback',state.result.status]" role="status"><div v-if="state.result.diagnosis" class="diagnosis-note"><strong>候选错因：{{ state.result.diagnosis.label }}</strong><p>{{ state.result.diagnosis.hint }}</p><small>{{ state.result.diagnosis.caveat }}</small></div><template v-else><strong>{{ state.result.label }}</strong><p>{{ state.result.feedback }}</p><small>{{ nextText }}</small></template><div class="task-actions"><span class="saved-attempt-receipt"><img :src="icon('check-circle')" alt="">本次作答已保存</span><button class="secondary-button" @click="setLessonTab('lecture')">先看看讲义</button><button v-if="nextTask" class="primary-button" :disabled="!!state.taskBusyId||state.evidenceBusy" @click="proceed">{{ state.result.diagnosis?'补上这一小步':nextTask===state.run.task.id?'再练一次':'从下一步继续' }}</button></div><details v-if="state.result.diagnosis" class="feedback-details"><summary>查看本题反馈</summary><p>{{ state.result.feedback }}</p></details></section>
<p class="help-condition-note">提示与导师答疑会留下帮助记录，受助完成与独立表现分别呈现。</p><button class="task-history-link" @click="setLessonTab('history')">本单元作答记录 <img :src="icon('chevron-right')" alt=""></button></section><section v-else class="task-loading" role="status"><p>{{ state.taskBusyId?'正在打开任务…':'当前任务暂未打开。' }}</p><button v-if="!state.taskBusyId&&currentLesson" class="secondary-button" @click="loadTaskById(state.retryAction?.task_id||currentLesson.tasks?.[0]?.id||currentLesson.practice.id)">重新打开任务</button></section></template>
